# פרק 5 (שלד אוטומטי מהתוכן הקיים; להעמקה)
N=5
TITLE='נזק וריחוק הנזק'
SUM=[' <p>אין נזיקין בלא <strong>נזק</strong>. שיעור זה — מהו נזק בר-פיצוי, ומתי נזק "רחוק מדי".</p> <h3>5.1 הגדרת נזק — סעיף 2</h3> <p>"נזק" — אובדן חיים, נכס, נוחות, רווחה גופנית או שם טוב, או חיסור מהם. כולל נזק <strong>ממוני</strong> (הוצאות, אובדן השתכרות) ו<strong>לא-ממוני</strong> (כאב וסבל, פגיעה באוטונומיה).</p> <h3>5.2 פיצויים וריחוק — סעיף 76</h3> <p><strong>סעיף 76(1)</strong>: פיצוי רק בשל נזק "שעלול לבוא באורח טבעי במהלכם הרגיל של הדברים ושבא במישרין מעוולת הנתבע". נזק "רחוק מדי" ובלתי צפוי אינו בר-פיצוי — מבחן הצפיות שולט (בעקבות <em>Wagon Mound</em>).</p> <h3>5.3 צפיות לפי סוג הנזק — רינגר</h3> <p>ב<strong>הלכת רינגר</strong> נקבע שנדרשת צפיות של <strong>סוג</strong> הנזק, לא של היקפו המדויק או דרך התרחשותו. די בצפיית נזק גוף כלשהו כדי לחוב על מכלול נזקי הגוף — כלל ה<strong>"גולגולת הדקה"</strong>.</p> <h3>5.4 נקודות מפתח למבחן</h3> <ul><li>נזק (ס׳ 2) — ממוני ולא-ממוני.</li><li>ריחוק נזק = חלק מהקשר המשפטי; מבחן הצפיות.</li><li>צפיות לפי סוג הנזק; גולגולת דקה (רינגר).</li></ul> <p style="margin-top:18px;padding-top:9px;border-top:1px solid var(--line,#3a342a);font-size:11px;color:var(--muted,#8a8475)">© כל הזכויות שמורות ל<b>אילן פרץ</b> · אין להעתיק, לשכפל או להפיץ ללא רשות בכתב.</p>']
CASES=[("ס' 2 לפקודת הנזיקין — הגדרת נזק", '', 'אובדן חיים, נכס, נוחות, רווחה גופנית או שם טוב — נזק ממוני ולא-ממוני כאחד.'), ("ס' 76 — פיצויים וריחוק", '', 'פיצוי רק בשל נזק שבא באורח טבעי ובמישרין מהעוולה; נזק רחוק מדי אינו בר-פיצוי.'), ('הלכת רינגר — צפיות סוג הנזק', '', 'נדרשת צפיות של סוג הנזק ולא של היקפו/דרכו; בסיס לכלל "הגולגולת הדקה".'), ('ע״א 390/62 רינגר נ׳ ליאון', 'נפגע בתאונת דרכים בגבו, ובשל רגישות נדירה התפתח אצלו גידול סרטני באזור החבלה.', 'נקבע שבריחוק הנזק הצפיות נדרשת לגבי סוג הנזק בלבד ולא לגבי היקפו או הליך התפתחותו. משנזק גוף היה צפוי, הנתבע אחראי לכל נזקי הגוף שהתפתחו — זה גם העיגון של הלכת הגולגולת הדקה בישראל.'), ('ע״א 223/80 בן ציון נ׳ מגורי בת-ים', 'אדם מעד על אבן שהושארה במדרכה ונפגע בידו. כשש שנים אחר כך, בעת טיפוס על סולם, תקף אותו כאב ביד הפגועה, הוא נפל ונפגע בברכו.', 'אף שמדובר באותו סוג נזק (גוף), נקבע שהפגיעה בברך רחוקה מדי בשל המרחק בזמן ובמקום והליך הגרימה הבלתי צפוי. הפסק ריכך את רינגר: גם הליך הגרימה רלוונטי לריחוק הנזק.'), ('דנ״א 7794/98 משה נ׳ קליפורד', 'ילדה קיבלה זריקת הרדמה בטיפול שיניים שגרתי וסבלה מנזק מוחי קשה ומשיתוק, בעוד שהתופעות הצפויות היו נמנום וסחרחורת.', 'ברוב דעות הוטלה אחריות. השופט ת׳ אור ראה בשיתוק נזק שניוני מאותו סוג של הנזק הצפוי, ולכן די בצפיות הסוג; שופטים אחרים סיווגו אותו כנזק ראשוני שהליך גרימתו צריך להיות צפוי. הפרשה מדגימה שהסיווג יכול להכריע.'), ('ע״א 8109/95 קרנית נ׳ גינת', 'נפגעת תאונת דרכים, שאושפזה והועברה לשיקום, קפצה מקומה רביעית בניסיון להתאבד, ותבעה גם את נזקי הניסיון.', 'נזקי ניסיון ההתאבדות הוכרו כהתפתחות טבעית של הנכות שגרמה התאונה, ולכן אינם רחוקים מדי ונכללים בפיצוי.'), ('רע״א 444/87 אלסוחה נ׳ עיזבון המנוח דוד דהאן ז״ל, פ״ד מד(3) 397 (1990)', 'דיון בתביעה של בני משפחה של נפגע, שסבלו נזק נפשי בעקבות הפגיעה בקרובם.', 'לראשונה הוכרה עילה של נפגע משני בגין נזק נפשי, בכפוף לשיקולים: קרבה משפחתית ראשונה, התרשמות ישירה, קרבה בזמן ובמקום לאירוע, ונזק נפשי ממשי — להבדיל מצער ויגון רגילים.'), ('ע״א 2781/93 דעקה נ׳ בית החולים ״כרמל״, חיפה', 'מטופלת שאושפזה לניתוח ברגל החתימה, כשהיא מטושטשת על שולחן הניתוחים, על הסכמה לביופסיה בכתף בלי שקיבלה הסבר; כתפה ״קפאה״.', 'נקבע שפגיעה בכבוד ובאוטונומיה בביצוע טיפול בלי הסכמה מדעת היא נזק בר-פיצוי וראש נזק עצמאי, גם כשלא הוכח קשר סיבתי לנזק הגוף (הוכח שהייתה מסכימה לטיפול).'), ('ע״א 1326/07 המר נ׳ עמית', 'בהרכב מורחב נדונו תביעות בגין רשלנות באבחון במהלך היריון, שבעקבותיה נולדו ילדים עם מומים.', 'עילת ״החיים בעוולה״ של הילד בוטלה — אין דרך ראויה לקבוע שחיים עם מוגבלות הם נזק לעומת אי-היוולדות. עילת ההורים הורחבה: הוצאות מוגברות של הילד לאורך חייו, נזק נפשי, ופיצוי על פגיעה באוטונומיה.')]
QS=[{'q': 'מדוע הנזק הוא יסוד הכרחי בעוולת הרשלנות?', 'o': ['כי הנזק הוא תנאי לחובת הזהירות', 'כי בלי נזק לא ניתן להגיש תביעה אזרחית כלל', 'כי כל העוולות בפקודה דורשות נזק', 'כי ס׳ 35 מגדיר כעוולה רק את מי ש״גורם ברשלנותו נזק לזולתו״'], 'c': 3, 'e': 'נכון. עוולת הרשלנות מוגדרת דרך גרימת הנזק, ולכן התרשלות בלי נזק אינה עוולה.'}, {'q': 'כיצד מגדיר ס׳ 2 לפקודה ״נזק״?', 'o': ['רק הפסד כספי שניתן לשומה', 'נגיעה שלא כדין בזכות משפטית', 'אבדן חיים, אבדן נכס, נוחות, רווחה גופנית או שם-טוב, או חיסור מהם, וכל אבדן או חיסור כיוצאים באלה', 'רק פגיעה פיזית בגוף או ברכוש'], 'c': 2, 'e': 'נכון. זו לשון ההגדרה; סיומה הפתוח מאפשר הכרה בסוגי נזק חדשים.'}, {'q': 'מה התנאים של ס׳ 4 (מעשה של מה בכך)?', 'o': ['שהתובע אינו רגיש במיוחד', 'שהמעשה, אילו חזר, לא היה יוצר זכות נוגדת, ואדם בר-דעת ומזג כרגיל לא היה מתלונן', 'שהנזק קטן מ-1,000 ש״ח', 'שהנתבע פעל בתום לב'], 'c': 1, 'e': 'נכון. שני תנאים מצטברים, והמבחן אובייקטיבי לפי אדם בר-דעת ומזג כרגיל.'}, {'q': 'מה קובע ס׳ 76(2) לפקודה?', 'o': ['שתאגיד אינו זכאי לפיצוי לא ממוני', 'שנזק נפשי אינו בר-פיצוי', 'שפיצויים לא יינתנו על נזק עתידי', 'שנזק ממון לא יפוצה אלא אם פורט בכתב התביעה או בצירוף לו'], 'c': 3, 'e': 'נכון. זו דרישת הפירוט לנזק ממון — הבסיס להבחנה בין נזק מיוחד לנזק כללי.'}, {'q': 'מה עמדת ההלכה הישראלית לגבי נזק כלכלי טהור?', 'o': ['הוא ״נזק״, וההגבלה על הפיצוי נעשית בשלב חובת הזהירות לפי שיקולי מדיניות', 'הוא מפוצה תמיד, כמו נזק גוף', 'הוא מפוצה רק בהפרת חוזה', 'הוא אינו ״נזק״ לפי ס׳ 2'], 'c': 0, 'e': 'נכון. כך פסק השופט ברק בע״א 243/83 גורדון; השאלה היא אם יש חובה לפצות, לא אם יש נזק.'}, {'q': 'אישה צפתה בתאונה שבה נפגע בנה הקטין ממש לנגד עיניה, ופיתחה הפרעת דחק פוסט-טראומטית מאובחנת. מה הדין לפי הלכת אלסוחה?', 'o': ['יש לה עילה רק לפיצוי על הוצאות רפואיות', 'יש לה עילה כנפגעת משנית — קרבה ראשונה, התרשמות ישירה, קרבה בזמן ובמקום ונזק נפשי ממשי', 'יש לה עילה רק אם נפגעה גם פיזית', 'אין לה עילה, כי רק הנפגע הישיר תובע'], 'c': 1, 'e': 'נכון. כל ארבעת השיקולים מתקיימים, ולכן היא זכאית לפיצוי על נזקה הנפשי.'}, {'q': 'דודו של נפגע שמע על התאונה כעבור שבוע, והיה עצוב ומדוכדך תקופה, בלי אבחנה של הפרעה נפשית. האם הוא זכאי לפיצוי כנפגע משני?', 'o': ['כן, אם יוכיח שהוא אוהב את הנפגע', 'כן, כי כל צער מפוצה לפי ס׳ 2', 'ככלל לא — הקרבה המשפחתית רחוקה, אין התרשמות ישירה, וצער רגיל אינו נזק נפשי ממשי', 'כן, כי הוא קרוב משפחה'], 'c': 2, 'e': 'נכון. רוב תנאי אלסוחה אינם מתקיימים, ובפרט חסר נזק נפשי ממשי.'}, {'q': 'רופא ביצע ניתוח בלי לקבל הסכמה מדעת. הוכח שהמטופל היה מסכים לניתוח אילו קיבל הסבר מלא, והניתוח הסתבך. לפי הלכת דעקה, למה הוא זכאי?', 'o': ['לפיצוי עונשי בלבד', 'לשום פיצוי, כי היה מסכים בכל מקרה', 'לפיצוי מלא על הסיבוך', 'לפיצוי על פגיעה באוטונומיה, גם בלי פיצוי על נזק הגוף'], 'c': 3, 'e': 'נכון. הפגיעה בזכות לבחור היא ראש נזק עצמאי; נזק הגוף לא יפוצה כי חסר קשר סיבתי.'}, {'q': 'מה נפסק בע״א 1326/07 המר נ׳ עמית?', 'o': ['שתביעות כאלה אינן אפשריות כלל', 'שגם הילד וגם ההורים זכאים לפיצוי כבעבר', 'שעילת ״החיים בעוולה״ של הילד בוטלה, ועילת ההורים הורחבה', 'שרק הילד זכאי לפיצוי'], 'c': 2, 'e': 'נכון. אי אפשר לקבוע שחיים עם מוגבלות הם נזק, אבל ההורים זכאים להוצאות המוגברות לאורך חיי הילד, לנזק נפשי ולפגיעה באוטונומיה.'}, {'q': 'מהי ההבחנה בין נזק ראשוני לנזק שניוני, ומה חשיבותה?', 'o': ['ראשוני — נגרם ישירות מהאשם (ונבחן בקשר סיבתי); שניוני — התפתח ממנו בתהליך מובחן (ונבחן בריחוק הנזק)', 'אין לה חשיבות מעשית', 'ראשוני — נזק גוף; שניוני — נזק רכוש', 'ראשוני — נזק שפורט בכתב התביעה; שניוני — נזק שלא פורט'], 'c': 0, 'e': 'נכון. ס׳ 64 עוסק בקשר לנזק הראשוני; ס׳ 76(1) בנזקים שהתפתחו ממנו.'}, {'q': 'לפי הלכת רינגר, מה צריך להיות צפוי כדי שנזק שניוני יפוצה?', 'o': ['כל שלבי התפתחות הנזק', 'זהות הרופא שיטפל בניזוק', 'סוג הנזק', 'היקף הנזק המדויק'], 'c': 2, 'e': 'נכון. די בצפיות סוג הנזק; לכן משנזק גוף צפוי, כל נזקי הגוף שהתפתחו ממנו ברי-פיצוי.'}, {'q': 'נפגע תאונה שבר את ידו. שש שנים אחר כך כאב פתאומי ביד גרם לו ליפול מסולם ולשבור את רגלו. לפי בן ציון נ׳ מגורי בת-ים, מה הדין לגבי השבר ברגל?', 'o': ['עשוי להיות רחוק מדי, בשל המרחק בזמן ובמקום והליך הגרימה החריג', 'בר-פיצוי רק אם פורט בכתב התביעה', 'בר-פיצוי, כי זה אותו סוג נזק — נזק גוף', 'בר-פיצוי, כי הגולגולת הדקה חלה'], 'c': 0, 'e': 'נכון. בפרשה נקבע שהנזק לברך רחוק מדי — צפיות הסוג אינה מכריעה כשהליך הגרימה חריג.'}, {'q': 'נפגעת תאונת דרכים ניסתה להתאבד במהלך השיקום. לפי קרנית נ׳ גינת, האם נזקי הניסיון ברי-פיצוי?', 'o': ['כן — הם הוכרו כהתפתחות טבעית של הנכות שנגרמה בתאונה', 'לא — התאבדות היא תמיד גורם זר מתערב', 'לא — נזק נפשי אינו מפוצה בתאונות דרכים', 'כן — אבל רק בשיעור 50%'], 'c': 0, 'e': 'נכון. בית המשפט ראה בניסיון ההתאבדות חלק מהשתלשלות טבעית של הפגיעה, ולכן לא רחוק מדי.'}, {'q': 'אדם נחבל קלות בתאונה, אך בשל מחלת לב שלא הייתה ידועה לקה בהתקף לב קשה. הנתבע טוען שלא יכול היה לצפות זאת. מה הדין?', 'o': ['הנתבע אחראי למלוא הנזק — המזיק מקבל את הניזוק כמות שהוא', 'הנתבע פטור, כי הנזק אינו צפוי', 'האחריות מתחלקת בין הנתבע לניזוק כאשם תורם', 'הנתבע אחראי רק לחבלה הקלה'], 'c': 0, 'e': 'נכון. נזק גוף היה צפוי, וחומרתו הבלתי צפויה בשל רגישות הניזוק היא עניין של היקף — המזיק נושא בה במלואה.'}, {'q': 'על מה אינה חלה הלכת הגולגולת הדקה?', 'o': ['על נזקים שניוניים שהתפתחו מהנזק הראשוני', 'על נזק גוף שנגרם לניזוק רגיש במיוחד', 'על סוג הנזק הראשוני ועל הליך גרימתו', 'על חומרה בלתי צפויה של הנזק הראשוני'], 'c': 2, 'e': 'נכון. ההלכה עוסקת בהיקף הנזק; אם סוג הנזק הראשוני עצמו אינו צפוי, היא אינה מצילה את התביעה.'}, {'q': 'לניזוק הייתה נכות קודמת בגב בשיעור 20%. התאונה החמירה אותה לנכות של 40%. לגבי מה אחראי המזיק?', 'o': ['ל-20% בלבד, כי זו הייתה הנכות הקודמת', 'רק להחמרה שגרם — לא לנכות הקודמת', 'לכל 40% הנכות', 'לשום דבר, כי הניזוק כבר היה נכה'], 'c': 1, 'e': 'נכון. המזיק אחראי לכל ההחמרה שגרם, אך מנכים את מה שהיה קיים בלאו הכי.'}, {'q': 'במה שונה מבחן הישירות (Polemis) ממבחן הצפיות (Wagon Mound)?', 'o': ['הצפיות מחייב בכל נזק, והישירות רק בנזק צפוי', 'הישירות מחייב בכל נזק ישיר גם בלתי צפוי; הצפיות רק בנזק שאדם סביר היה צופה', 'הישירות חל רק על נזקי רכוש', 'אין הבדל'], 'c': 1, 'e': 'נכון. בישראל, למרות לשון ס׳ 76(1), אומץ מבחן הצפיות, לגבי סוג הנזק (מלכה, רינגר).'}, {'q': 'נפגע תאונת דרכים נותח ברשלנות בבית חולים, ונזקו הוחמר. לפי הלכת חוסיין, ממי יקבל פיצוי על ההחמרה?', 'o': ['מהמבטח לפי חוק הפיצויים, בלי שהמבטח יוכל לחזור אל בית החולים', 'מאף אחד, כי זה גורם זר מתערב', 'מבית החולים בלבד, לפי פקודת הנזיקין', 'מהמבטח לפי חוק הפיצויים, והמבטח יחזור לבית החולים'], 'c': 0, 'e': 'נכון. ההחמרה עקב הטיפול נכללת בתביעה לפי החוק, והמבטח אינו יכול לשלוח הודעת צד ג׳ לרופא או לבית החולים.'}, {'q': 'מה ההבדל בין ״נזק״ לבין ״פגיעה״ לפי ס׳ 2?', 'o': ['״פגיעה״ היא נזק פיזי בלבד, ״נזק״ הוא נזק כלכלי', 'אין הבדל, אלה מילים נרדפות', '״פגיעה״ היא נגיעה שלא כדין בזכות משפטית; ״נזק״ הוא האבדן או החיסור שנגרם', '״נזק״ חל רק על תאגידים'], 'c': 2, 'e': 'נכון. זו לשון ההגדרות; ברשלנות דרוש נזק, ולא די בפגיעה בזכות.'}, {'q': 'מה הדגים השופט ח׳ כהן בפרשת רינגר כנזק ״רחוק מדי״?', 'o': ['נזק לילדי הנפגע, שנאלצו לוותר על קריירה כי אביהם פשט רגל בעקבות הפגיעה', 'הוצאות רפואיות של הנפגע', 'כאב וסבל של הנפגע', 'גידול סרטני שהתפתח מהחבלה'], 'c': 0, 'e': 'נכון. נזק כזה אינו ״טבעי״, ״רגיל״ ו״ישיר״ — ולכן רחוק מדי לפי ס׳ 76(1).'}, {'q': 'היכן מוגדר "נזק"?', 'o': ["ס' 64", "ס' 2", "ס' 35", "ס' 68"], 'c': 1, 'e': "הגדרה רחבה בס' 2."}, {'q': 'נזק לא-ממוני כולל:', 'o': ['אובדן השתכרות', 'כאב וסבל', 'הוצאות רפואיות', 'נזק לרכוש'], 'c': 1, 'e': 'כאב וסבל, פגיעה באוטונומיה.'}, {'q': "מטרת הפיצוי (ס' 76):", 'o': ['ענישת המזיק', 'השבת המצב לקדמותו', 'רווח לניזוק', 'הרתעה בלבד'], 'c': 1, 'e': 'אינטרס הפיצוי.'}, {'q': 'ריחוק הנזק נבחן לפי:', 'o': ['גובה הנזק', 'מבחן הצפיות', 'אשם תורם', 'עלות מניעה'], 'c': 1, 'e': 'נזק רחוק/בלתי צפוי אינו בר-פיצוי.'}, {'q': 'לפי הלכת רינגר נדרשת צפיות של:', 'o': ['היקף הנזק המדויק', 'סוג הנזק', 'דרך ההתרחשות', 'זהות הניזוק'], 'c': 1, 'e': 'די בצפיית סוג הנזק.'}]
